KG42.register("rules-e623d7904c3f813fa12568e1",{"id":"24-brooklyn_microgrid::v141-c-R007","paper":"24-brooklyn_microgrid","record":{"rule_id":"v141-c-R007","mechanism_id":"v141-a-M01","name":"Counterparty matching","process_stage":"matching","market_meaning":"Submitted buy orders, which include requested quantities, provide inputs to counterparty matching. Scope: C4 microgrid energy-market design: matching participants’ buy and sell orders. Submitted sell orders, which include offered quantities, provide inputs to counterparty matching. Scope: C4 microgrid energy-market design: matching participants’ buy and sell orders.","independence_rationale":"Relations governed by the approved function matching.counterparties under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","bidding.supply","matching.counterparties"],"E":[{"edge_id":"v141-c-R007-E001","source":"bidding.demand","target":"matching.counterparties","type":"links","constraint_ids":["v141-c-R007-C001"],"evidence_ids":["v141-b-g02-e04","v141-b-g02-e09"]},{"edge_id":"v141-c-R007-E002","source":"bidding.supply","target":"matching.counterparties","type":"links","constraint_ids":["v141-c-R007-C002"],"evidence_ids":["v141-b-g02-e04","v141-b-g02-e09"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"matching","context_text":"C4 microgrid energy-market design: matching participants’ buy and sell orders.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e04","v141-b-g02-e09"]},"x":[],"theta":[],"phi":[{"constraint_id":"v141-c-R007-C001","kind":"procedural","role":"core","statement":"Submitted buy orders, which include requested quantities, provide inputs to counterparty matching. Scope: C4 microgrid energy-market design: matching participants’ buy and sell orders.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","matching.counterparties"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e04","v141-b-g02-e09","v141-b-g02-e05","v141-b-g02-e11","v141-b-g02-e30","v141-b-g02-e35"]},{"constraint_id":"v141-c-R007-C002","kind":"procedural","role":"core","statement":"Submitted sell orders, which include offered quantities, provide inputs to counterparty matching. Scope: C4 microgrid energy-market design: matching participants’ buy and sell orders.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply","matching.counterparties"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e04","v141-b-g02-e09","v141-b-g02-e05","v141-b-g02-e11","v141-b-g02-e30","v141-b-g02-e35"]}],"pi":[{"evidence_id":"v141-b-g02-e04","location":{"location_id":"src-d1d75d8eed-p07-c2r3__v141-a-M01-bidding","page":7,"printed_page":null,"section":"4.2 Market mechanism","anchor_text":"g pp y g ensured without the traditional grid. The BMG’s market mechanism is implemented on the Tran","equation_id":null,"figure_id":"Fig. 6","table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"definition"},"source_text":"Any prosumer $P_g$ and consumer $C_a$ willing to trade electricity in the next time slot, can submit buy or sell orders via their EMTS (C6) to the market. Any order includes an order quantity and price. The market mechanism (C4) is a closed order book with a time discrete double auction in 15 min time slots. For now, consumers constantly bid their maximum price limit for their preferred energy sources (e.g. local renewable energy). Prosumers bid the minimum price limit that they request for selling their generation on the microgrid market."},{"evidence_id":"v141-b-g02-e09","location":{"location_id":"src-d1d75d8eed-p05-c2r4__v141-a-M01-matching","page":5,"printed_page":null,"section":"3.4 Market mechanism (C4)","anchor_text":"( ) The market mechanism comprises the market’s allocation and payment rules, and provides an employ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"The market mechanism comprises the market’s allocation and payment rules, and provides an employable bidding language and a clearly defined bidding format [50]. The market mechanism is implemented by the information system (C3). Its main objective is to provide an efficient allocation of the traded energy by matching the market participants’ buy and sell orders [31]. This should best be done in (near) real time granularity [31]."},{"evidence_id":"v141-b-g02-e05","location":{"location_id":"src-d1d75d8eed-p07-c2r4__v141-a-M01-bidding","page":7,"printed_page":null,"section":"4.2 Market mechanism","anchor_text":", stantly bid their maximum price limit for their preferred energy sources (e.g. local renewable ene","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"example"},"source_text":"For example, consumer $C_1$ bids a maximum price $x_1$ for quantity $y_1$, prosumer $P_{24}$ offers quantity $y_{24}$ for a minimum price of $x_{24}$."},{"evidence_id":"v141-b-g02-e11","location":{"location_id":"src-d1d75d8eed-p07-c2r4__v141-a-M01-clearing","page":7,"printed_page":null,"section":"4.2 Market mechanism","anchor_text":", stantly bid their maximum price limit for their preferred energy sources (e.g. local renewable ene","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"example"},"source_text":"Similar to a merit-order dispatch, the highest bidder is allocated first, then the lower bidders are allocated. The last allocated bid price represents the market clearing price for this time slot (C5). Consumers that do not undercut the clearing price will be supplied by additional energy sources (i.e. hyper-local energy or traditional “brown” energy) allocated over a similar bidding mechanism or predefined prices. This is well in line with the market mechanism presented by Ilic et al. [26]."},{"evidence_id":"v141-b-g02-e30","location":{"location_id":"src-d1d75d8eed-p05-c1r2__v141-a-M01-matching","page":5,"printed_page":null,"section":"Fig. 3","anchor_text":"Fig. 3. A schematic overview of the seven market components. The upper two orders in the pricing mec","equation_id":null,"figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"example"},"source_text":"Fig. 3. A schematic overview of the seven market components. The upper two orders in the order book would be matched. The transaction price will be determined by the pricing mechanism and paid in monetary units (MU)."},{"evidence_id":"v141-b-g02-e35","location":{"location_id":"src-d1d75d8eed-p07-c1r3__v141-a-M01-matching","page":7,"printed_page":null,"section":"4.1 Project overview","anchor_text":"g remaining power. The physical microgrid currently comprises ens 10-by-10 housing blocks and will b","equation_id":null,"figure_id":"Fig. 5","table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"definition"},"source_text":"Buy and ask orders are created according to this information, and orders are send to the market mechanism (C4) that is sustained by a smart contract. Once the matching is completed, payment is carried out and a new block (here Block iv) is added to the blockchain. This block includes all current market information. The required information (i.e. conducted transactions) is also send to the involved agents via their blockchain accounts."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":"The R007 evidence describes matching as a process consuming submitted buy and sell orders and does not specify a design or operational decision variable for the matching rule. Order quantity and price appear only as order attributes, with no matching formula or variable domains stated.","empty_theta_reason":"No fixed parameter, coefficient, bound, or mathematical constant specific to counterparty matching is defined in the supplied R007 evidence. The 15-minute time-slot mention is market-mechanism context and is not used here in an explicit matching expression."},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-matching","v141-a-M01-settlement"],"extras":{"decision_anchor":"matching.counterparties","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e09","quote":"Its main objective is to provide an efficient allocation of the traded energy by matching the market participants’ buy and sell orders [31]."},{"evidence_id":"v141-b-g02-e04","quote":"Any order includes an order quantity and price."}],[{"evidence_id":"v141-b-g02-e09","quote":"Its main objective is to provide an efficient allocation of the traded energy by matching the market participants’ buy and sell orders [31]."},{"evidence_id":"v141-b-g02-e04","quote":"Any order includes an order quantity and price."}]],"C2_formalization":{"graph_sha256":"10e593a1a0c42f95429357a3d14f6ba4831c63d8efec21b257bb68f4454cf94e","applicability":"non_mathematical","reason":"R007 describes counterparty matching procedurally: submitted buy and sell orders, each with quantity and price, are inputs to the C4 market mechanism, whose objective is allocation by matching participants' buy and sell orders. The supplied R007 evidence does not state a matching formula, allocation rule, priority/tie-break equation, order domain, coefficient, bound, or mathematical parameter for counterparty matching. The 15-minute double-auction context in e04 is market-mechanism context, but no explicit matching expression is available. This rule is therefore treated as a non-mathematical procedural rule without adding invented mathematics; the cited B evidence remains unreviewed.","bindings":[{"object_id":"v141-c-R007-C001","node_ids":["bidding.demand","matching.counterparties"],"edge_ids":["v141-c-R007-E001"],"rationale":"C001 is the frozen C.1 procedural statement for the E001 link from submitted demand orders to counterparty matching; the rule supplies no quantitative expression for this link."},{"object_id":"v141-c-R007-C002","node_ids":["bidding.supply","matching.counterparties"],"edge_ids":["v141-c-R007-E002"],"rationale":"C002 is the frozen C.1 procedural statement for the E002 link from submitted supply orders to counterparty matching; the rule supplies no quantitative expression for this link."}],"revision_requests":[]}},"quarantined_references":[]}});
